 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('7bea0e93-0594-5935-87e6-9b202c5daa5d'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'Que signifie étymologiquement le mot démocratie ?', 'mcq', '["Le pouvoir du peuple","Le pouvoir de la loi","Le gouvernement des meilleurs","Le pouvoir du plus grand nombre de riches"]'::jsonb, 0, 'Dêmos, le peuple, et kratos, le pouvoir.', 1),
    ('6d6684f7-bd0a-5d53-ae95-c42b6b9ccfa8'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'Quel critère distingue le mieux une démocratie d’un régime autoritaire ?', 'mcq', '["La possibilité réelle de perdre le pouvoir et de le céder","La tenue d’élections","L’existence d’une constitution","La présence d’un parlement"]'::jsonb, 0, 'Beaucoup de régimes autoritaires organisent des élections.', 2),
    ('6fb9ce3f-c3de-5451-b145-2cdf377661f3'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'Qui a énoncé le principe de séparation des pouvoirs ?', 'mcq', '["Montesquieu","Rousseau","Tocqueville","Voltaire"]'::jsonb, 0, 'Exécutif, législatif et judiciaire ne doivent pas se confondre.', 3),
    ('47fc9ff6-1535-5ff0-93e1-3c6cb3c2ccfe'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'Quel régime permet au parlement de renverser le gouvernement ?', 'mcq', '["Le régime parlementaire","Le régime présidentiel","Le régime autoritaire","Aucun"]'::jsonb, 0, 'Aux États-Unis, régime présidentiel, le Congrès ne le peut pas.', 4),
    ('91479ed2-8ffb-5b20-9cbc-7f1708b97e0e'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'La Ve République française est un régime semi-présidentiel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Président élu au suffrage universel direct et gouvernement responsable devant l’Assemblée.', 5),
    ('48a0ec11-0391-5ecf-8f00-63a8436b132c'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'Qu’est-ce qu’un régime dit « illibéral » ?', 'mcq', '["Un régime qui conserve les élections mais affaiblit presse, justice et contre-pouvoirs","Un régime sans élections","Une monarchie absolue","Un régime militaire"]'::jsonb, 0, 'Leur montée explique l’érosion démocratique constatée depuis une quinzaine d’années.', 6),
    ('808fa112-9595-5db3-98c0-aa66750552c2'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'Que vise la démocratie participative ?', 'mcq', '["Associer les citoyens à la décision entre deux élections","Remplacer les élections par le tirage au sort","Supprimer les partis politiques","Renforcer le pouvoir exécutif"]'::jsonb, 0, 'Budgets participatifs et conventions citoyennes en sont des formes.', 7),
    ('75d6443b-5516-5770-8179-e56f3f91b623'::uuid, '501c476e-3bef-5530-b9b2-e0be8de64b09'::uuid, 'L’État de droit signifie que les gouvernants sont eux-mêmes soumis à la loi.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et qu’une juridiction peut censurer la loi elle-même.', 8),
    ('52c304b1-d677-5179-854a-2f5f4c4ea6a0'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Comment étaient désignés la plupart des magistrats athéniens ?', 'mcq', '["Par tirage au sort","Par élection","Par hérédité","Par nomination du stratège"]'::jsonb, 0, 'Les stratèges, eux, étaient élus pour leur compétence militaire.', 1),
    ('1b14d09b-cf5d-58bb-927a-9c78bd1f9c3c'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Pourquoi le tirage au sort était-il jugé démocratique par les Grecs ?', 'mcq', '["Il donne à chacun une chance égale, quand l’élection favorise les notables","Il est plus rapide","Il évite les débats","Il désigne les plus compétents"]'::jsonb, 0, 'Point contre-intuitif, et régulièrement demandé.', 2),
    ('89749ea0-0525-54c9-aa17-f58ffe5a8913'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Qu’est-ce que l’Ecclésia ?', 'mcq', '["L’assemblée de tous les citoyens, qui vote les lois","Le conseil de 500 membres tirés au sort","Le tribunal populaire","Le collège des stratèges"]'::jsonb, 0, 'Elle se réunissait une quarantaine de fois par an sur la Pnyx.', 3),
    ('39bb5da6-410c-54d1-a902-4ce9514e245b'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Les femmes nées de parents athéniens étaient citoyennes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles étaient exclues de la citoyenneté, comme les métèques et les esclaves.', 4),
    ('69d8dacc-d488-5262-a6c9-e8eed7690b4a'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Qui sont les métèques ?', 'mcq', '["Des étrangers libres installés à Athènes, sans droit de vote","Des esclaves affranchis et devenus citoyens","Des citoyens exilés","Des soldats étrangers"]'::jsonb, 0, 'Ils paient l’impôt et servent à l’armée sans jamais voter.', 5),
    ('1f60a43b-5051-561f-b542-2ce9c18b887c'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'À quoi servait la misthophorie ?', 'mcq', '["À indemniser la participation, permettant aux plus pauvres de siéger","À punir les absents","À financer la flotte","À rémunérer les esclaves"]'::jsonb, 0, 'Sans elle, seuls les citoyens aisés auraient pu siéger.', 6),
    ('54191163-5a2a-5e67-857a-be51185e728d'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Qu’est-ce que l’ostracisme ?', 'mcq', '["L’exil pour dix ans d’un citoyen jugé trop puissant, décidé par vote","La privation de citoyenneté à vie","Une amende infligée aux orateurs","Le refus d’accorder la citoyenneté"]'::jsonb, 0, 'C’est un mécanisme de protection contre la tyrannie.', 7),
    ('7ef8c71a-196b-5c2b-b9c2-86afa396c4d2'::uuid, '8b3534e6-e999-5d9d-b6ea-57e79bc0308f'::uuid, 'Combien de citoyens comptait Athènes pour environ 300 000 habitants ?', 'mcq', '["Environ 40 000","Environ 150 000","Environ 10 000","Environ 250 000"]'::jsonb, 0, 'La participation intense reposait sur une exclusion massive.', 8),
    ('2c7fad9e-1b59-5f4f-8483-0366019e5b97'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'Que garantit le Bill of Rights anglais de 1689 ?', 'mcq', '["Que le roi ne peut lever l’impôt ni suspendre les lois sans le Parlement","Le suffrage universel","L’indépendance des colonies","L’abolition de la monarchie"]'::jsonb, 0, 'C’est l’acte de naissance de la monarchie parlementaire.', 1),
    ('3dc44c32-b756-5134-9926-ef484950d27f'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'Quel régime la Constitution américaine de 1787 institue-t-elle ?', 'mcq', '["Un régime présidentiel et fédéral","Une monarchie parlementaire","Un régime d’assemblée","Un régime semi-présidentiel"]'::jsonb, 0, 'Avec une séparation stricte et des contrôles réciproques.', 2),
    ('d2c84295-05d3-51b1-9f4f-999b5af216c5'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'Qu’est-ce que le suffrage censitaire ?', 'mcq', '["Un droit de vote réservé à ceux qui paient un certain niveau d’impôt","Un vote par tirage au sort","Un vote réservé aux hommes","Un vote indirect"]'::jsonb, 0, 'Il distingue citoyens actifs et passifs dans la Constitution de 1791.', 3),
    ('ba816474-6cc8-5b61-9ff3-bc2fb2291830'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'La Convention de 1792 est élue au suffrage universel masculin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une première, restée sans lendemain immédiat.', 4),
    ('9c634fd6-8aa2-5f2f-b532-29fed93dff5f'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'Qu’implique le mandat représentatif ?', 'mcq', '["L’élu représente la Nation entière et n’est pas révocable en cours de mandat","L’élu obéit aux instructions de ses électeurs","L’élu est tiré au sort","L’élu peut être révoqué à tout moment"]'::jsonb, 0, 'Il s’oppose au mandat impératif.', 5),
    ('4457d821-2565-5358-b182-7b1cc3efc1de'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'Comment Sieyès distingue-t-il démocratie et gouvernement représentatif ?', 'mcq', '["Dans la démocratie le peuple fait la loi, dans le gouvernement représentatif il choisit qui la fera","Il les tient pour synonymes","La démocratie serait réservée aux petits États seulement","Le gouvernement représentatif serait un régime monarchique"]'::jsonb, 0, 'Le choix du représentatif est politique, non seulement pratique.', 6),
    ('de8851e2-a408-529f-99fa-69a9ee722d1d'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'L’esclavage a été aboli partout dès les révolutions du XVIIIe siècle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il subsiste aux États-Unis et sera rétabli en France en 1802.', 7),
    ('424895f6-0391-5926-abac-c0e04c710e69'::uuid, '7801255a-7fce-56c5-adc0-88621768b087'::uuid, 'Sur quoi la Déclaration d’indépendance américaine de 1776 fonde-t-elle la légitimité ?', 'mcq', '["Sur des droits naturels et le consentement des gouvernés","Sur la volonté du roi","Sur la tradition coloniale","Sur un traité international"]'::jsonb, 0, 'C’est une rupture avec la légitimité par la naissance ou par Dieu.', 8),
    ('8bb6d679-4e1f-530d-aa1e-17adc67ee011'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Quel ouvrage Tocqueville tire-t-il de son voyage de 1831 ?', 'mcq', '["De la démocratie en Amérique","L’Ancien Régime et la Révolution","Du contrat social","De l’esprit des lois"]'::jsonb, 0, 'Publié en deux tomes, en 1835 et 1840.', 1),
    ('dfb41a91-165c-5793-8a15-f37d5f8f9fe4'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Comment Tocqueville qualifie-t-il l’égalisation des conditions ?', 'mcq', '["Un mouvement providentiel et irrésistible","Une mode passagère","Une spécificité américaine","Un recul de la civilisation"]'::jsonb, 0, 'Il pense que l’Europe suivra le même chemin.', 2),
    ('05a1b45a-f39a-5c5d-a084-864727c0179b'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Qu’est-ce que la tyrannie de la majorité ?', 'mcq', '["La pression de l’opinion majoritaire, qui ne laisse aucun recours à la minorité","Le vote d’une loi à une voix près","Le pouvoir d’un dictateur élu","Le règne des partis"]'::jsonb, 0, 'Le danger est moral avant d’être physique.', 3),
    ('55fe3400-4fc6-5bd2-9ce4-ec54f91e9c31'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Que désigne l’individualisme chez Tocqueville ?', 'mcq', '["Le repli sur le cercle privé et le détachement du public","L’égoïsme personnel","La défense des droits individuels","L’esprit d’entreprise"]'::jsonb, 0, 'Il fixe le sens de ce mot, distinct de l’égoïsme.', 4),
    ('4689fde3-97fd-56f5-a5a6-e6fece7761e4'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Qu’est-ce que le despotisme doux ?', 'mcq', '["Un pouvoir tutélaire qui infantilise et à qui les citoyens consentent","Une dictature militaire","Une monarchie éclairée","Un pouvoir religieux"]'::jsonb, 0, 'Il est compatible avec les formes extérieures de la souveraineté populaire.', 5),
    ('0fa1a60f-f0b4-53e6-a455-7d125a106694'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Tocqueville admire la vitalité des associations américaines.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles forment à l’action collective et font contrepoids à l’État.', 6),
    ('af221eb4-bf68-568f-9223-60d514a6b790'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Quels remèdes Tocqueville oppose-t-il aux périls de la démocratie ?', 'mcq', '["Association, presse libre, décentralisation et justice indépendante","Le retour à la monarchie","La restriction du suffrage","Le renforcement du pouvoir central"]'::jsonb, 0, 'La liberté demande des institutions et des mœurs.', 7),
    ('9d352961-66d8-5fb3-92b6-9fc379a61ac2'::uuid, 'e58b63ed-e586-5e1b-ac03-b442d0f94317'::uuid, 'Selon Tocqueville, la liberté se conserve d’elle-même une fois acquise.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est précisément l’inverse qu’il soutient.', 8),
    ('64e74332-1771-555f-8ac7-1bd1836fe6df'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'Avec quel pourcentage Salvador Allende est-il élu en 1970 ?', 'mcq', '["36,6 %, sans majorité absolue","Plus de 50 %","Environ 45 %","Il n’a pas été élu"]'::jsonb, 0, 'Il est ensuite confirmé par le Congrès.', 1),
    ('6337abbc-e21d-530d-907e-93b1ac782a6e'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'Quelle ressource Allende nationalise-t-il en priorité ?', 'mcq', '["Le cuivre","Le pétrole","Le lithium","Le blé"]'::jsonb, 0, 'Sans indemniser les compagnies américaines, ce qui envenime les relations.', 2),
    ('b6448d14-e173-52c9-ba82-f72c960cca43'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'Quelles difficultés économiques marquent le Chili de 1972-1973 ?', 'mcq', '["Une inflation vertigineuse, des pénuries et un marché noir","Une croissance record","Un excédent commercial","Une déflation"]'::jsonb, 0, 'La polarisation politique s’en trouve accélérée.', 3),
    ('bf087de1-232a-5a7c-802e-963a2096f73c'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'Quel rôle jouent les États-Unis dans la déstabilisation du Chili ?', 'mcq', '["Blocage du crédit international et financement de l’opposition","Envoi de troupes","Soutien économique à Allende","Aucun rôle"]'::jsonb, 0, 'La guerre froide en fournit le cadre.', 4),
    ('aa860f41-1fef-5ec4-b183-3c42b455fb11'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'À quelle date a lieu le coup d’État militaire chilien ?', 'mcq', '["Le 11 septembre 1973","Le 4 septembre 1970","Le 11 mars 1990","Le 5 octobre 1988"]'::jsonb, 0, 'Le palais de la Moneda est bombardé, Allende y meurt.', 5),
    ('011f555e-8a73-5c90-b5a8-19e6d25855d6'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'La dictature de Pinochet a duré jusqu’en 1990.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dissolution du Congrès, censure, torture, disparitions : dix-sept années.', 6),
    ('faa77d49-03ce-5dd0-8ed3-2e2316485d8e'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'Comment s’amorce le retour à la démocratie au Chili ?', 'mcq', '["Par le référendum de 1988, où le « non » l’emporte","Par une insurrection armée","Par une intervention étrangère","Par la mort de Pinochet"]'::jsonb, 0, 'Des élections suivent en 1989.', 7),
    ('885ba8d1-f236-5c7c-a770-d7b5e5f5e8f6'::uuid, '299d7f8c-6ca7-5b23-ae1a-fb268d76c85d'::uuid, 'Qu’a établi la commission Rettig ?', 'mcq', '["Le bilan des violations des droits humains sous la dictature","Le programme économique du régime","La constitution de 1980","Le calendrier électoral"]'::jsonb, 0, 'Plus de 3 000 morts et disparus, des dizaines de milliers de torturés.', 8),
    ('0256e6d2-d80d-594e-9960-66b4febd1ccf'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'Comment s’appelle le régime dictatorial portugais fondé par Salazar ?', 'mcq', '["L’Estado Novo","Le Franquisme","La Falange","Le Salazarisme constitutionnel"]'::jsonb, 0, 'Fondé en 1933, poursuivi ensuite par Caetano.', 1),
    ('6e320599-d74f-5b1b-be66-0c7247099751'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'Qu’est-ce qui épuise le régime portugais avant 1974 ?', 'mcq', '["Les guerres coloniales menées depuis 1961","Une crise financière internationale","Une épidémie","Un conflit avec l’Espagne"]'::jsonb, 0, 'Elles absorbent près de la moitié du budget de l’État.', 2),
    ('9f1620ef-f2af-5d4f-8e2b-86bc101959b1'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'À quelle date a lieu la révolution des Œillets ?', 'mcq', '["Le 25 avril 1974","Le 20 novembre 1975","Le 23 février 1981","Le 11 septembre 1973"]'::jsonb, 0, 'Un mouvement d’officiers renverse le régime presque sans effusion de sang.', 3),
    ('7cfdb596-ac8a-5383-9186-b4b641f797e1'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'Qui a désigné Juan Carlos pour lui succéder en Espagne ?', 'mcq', '["Franco lui-même","Les Cortès élues","Adolfo Suárez","Le peuple par référendum"]'::jsonb, 0, 'Le roi choisit pourtant d’ouvrir le régime.', 4),
    ('82409fa8-37c3-5ec1-b37b-dd864c9a71f4'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'Qu’ont fait les Cortès franquistes en 1976 ?', 'mcq', '["Elles ont voté leur propre disparition","Elles ont refusé toute réforme","Elles ont proclamé la république","Elles ont dissous les partis"]'::jsonb, 0, 'La loi de réforme politique est ensuite approuvée par référendum.', 5),
    ('1e0c6c5f-33c4-50e9-af4a-010779d3bf4d'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'Que sont les pactes de la Moncloa ?', 'mcq', '["Un accord économique et social entre gouvernement, patronat et syndicats en 1977","Un traité international","La constitution espagnole","Un accord militaire"]'::jsonb, 0, 'Ils sont l’un des deux appuis de la transition.', 6),
    ('c0d5bff0-bed6-566e-9bef-e6af0418e138'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'La tentative de coup d’État de février 1981 en Espagne a réussi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le refus public de Juan Carlos la fait échouer.', 7),
    ('b3f235cb-591e-5fdc-9e83-cc3dc13f7fda'::uuid, 'ac5a33a8-ac83-58ba-af53-fdf6483b1f5c'::uuid, 'Qu’ont en commun le Portugal et l’Espagne en 1986 ?', 'mcq', '["Ils adhèrent tous deux à la Communauté économique européenne","Ils deviennent des républiques","Ils organisent leurs premières élections","Ils adoptent leur constitution"]'::jsonb, 0, 'L’adhésion scelle leur ancrage démocratique.', 8),
    ('5f8c07f3-6edb-5e46-858e-4468b66fb8fb'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Depuis quand le Parlement européen est-il élu au suffrage universel direct ?', 'mcq', '["1979","1957","1992","2009"]'::jsonb, 0, 'Ses pouvoirs se sont ensuite considérablement étendus.', 1),
    ('53320a8f-9fed-5aea-9a00-dabcde9b66d5'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Quelle institution européenne a le monopole de l’initiative législative ?', 'mcq', '["La Commission","Le Parlement","Le Conseil de l’Union","La Cour de justice"]'::jsonb, 0, 'Ses membres étant nommés, c’est une source du reproche de technocratie.', 2),
    ('70886754-f278-55cb-af91-7ff9589a6fff'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Que reproche-t-on à l’Union sous le nom de « déficit démocratique » ?', 'mcq', '["Initiative non élue, complexité, abstention et absence d’espace public européen","L’absence de parlement","L’absence de tribunal","Le refus des référendums"]'::jsonb, 0, 'Les élections européennes se jouent souvent sur des enjeux nationaux.', 3),
    ('21f77ef9-e540-556b-abc2-e8d334d53325'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Qu’est-ce que le principe de subsidiarité ?', 'mcq', '["L’Union n’agit que si son action est plus efficace que celle des États","Les États obéissent toujours à l’Union","Chaque État applique le droit à sa guise","Le Parlement délègue ses pouvoirs"]'::jsonb, 0, 'Il vise à borner l’intervention européenne.', 4),
    ('6894c39e-fc47-5ed9-904c-08adb758d559'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Qu’ont rejeté les référendums français et néerlandais de 2005 ?', 'mcq', '["Le traité constitutionnel européen","L’adhésion de nouveaux États","La monnaie unique","La Charte des droits fondamentaux"]'::jsonb, 0, 'Un texte de portée réduite sera adopté ensuite par voie parlementaire.', 5),
    ('514b0b95-eec2-5f93-8059-bb200c2653ed'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'L’initiative citoyenne européenne permet à un million de citoyens de saisir la Commission.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils peuvent lui demander de proposer un texte, sans l’y obliger.', 6),
    ('7de43b6a-0762-515a-9e30-652cbc6b84c6'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Que montre le Brexit du point de vue institutionnel ?', 'mcq', '["Qu’une sortie de l’Union est possible","Que l’Union est irréversible","Que le Parlement peut exclure un État","Que les traités interdisent le retrait"]'::jsonb, 0, 'Voté en 2016, effectif en 2020.', 7),
    ('bfd1fc95-777b-537e-ad94-d271d985caa4'::uuid, 'cb6c9c7d-f92d-500a-b80d-6fe51f1190da'::uuid, 'Quelle est la nature de la légitimité du Conseil de l’Union ?', 'mcq', '["Indirecte, tirée des gouvernements nationaux","Directe, par élection","Judiciaire","Aucune"]'::jsonb, 0, 'Il réunit les ministres des États membres.', 8),
    ('679f9862-e454-584b-9fba-1a89bf1d37d6'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Comment définit-on la puissance en relations internationales ?', 'mcq', '["La capacité d’imposer sa volonté et de résister à celle des autres","La taille du territoire","Le nombre d’habitants","La richesse par habitant"]'::jsonb, 0, 'Elle se mesure à ce qu’un acteur obtient, non à ce qu’il possède.', 1),
    ('6715eddb-7865-5a04-9d2c-e1d52b9135ad'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Qu’est-ce que le soft power selon Joseph Nye ?', 'mcq', '["La capacité d’obtenir par l’attraction plutôt que par la contrainte","La force militaire conventionnelle","Les sanctions économiques","La diplomatie secrète"]'::jsonb, 0, 'Culture, valeurs, langue, universités et industries culturelles.', 2),
    ('abff4d85-485a-539d-808f-b12248301c2e'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Qu’appelle-t-on smart power ?', 'mcq', '["L’art de combiner hard et soft power à propos","La puissance technologique","L’espionnage","La puissance des algorithmes"]'::jsonb, 0, 'Aucun des deux ne suffit seul.', 3),
    ('f708e246-a8a1-56f4-a8aa-5e1a9c2811ff'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Seuls les États peuvent être des acteurs de puissance aujourd’hui.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Firmes multinationales, ONG et plateformes numériques en sont aussi.', 4),
    ('2dc68614-000b-5516-b5d8-29211f4d48ed'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Comment qualifie-t-on le système international de la guerre froide ?', 'mcq', '["Bipolaire","Unipolaire","Multipolaire","Apolaire"]'::jsonb, 0, 'La période suivant 1991 est souvent dite unipolaire.', 5),
    ('3f3fd856-a6e3-5162-a13b-960081b55fab'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Le soft power se décrète par une politique publique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se constate : c’est l’attraction effectivement exercée qui le mesure.', 6),
    ('4e7c4c29-b570-5349-bf22-c1a42d948fbb'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Quels sont les nouveaux terrains d’exercice de la puissance ?', 'mcq', '["Le cyberespace, l’espace, les normes et les données","Les colonies","Les zones polaires uniquement","Les fleuves internationaux"]'::jsonb, 0, 'Un acteur privé peut y peser autant qu’un État.', 7),
    ('6c6472dc-0b08-555d-9a46-82a40757c2fd'::uuid, 'c1c5a350-c80c-5920-9927-dd1ba9b395d8'::uuid, 'Que confère un siège permanent au Conseil de sécurité de l’ONU ?', 'mcq', '["Un droit de veto sur les résolutions","Le commandement des forces de l’ONU","Un budget supplémentaire","La présidence tournante"]'::jsonb, 0, 'C’est un attribut classique de la puissance diplomatique.', 8),
    ('e858dff1-ca77-5fa5-9db2-7dc31ab4aa29'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Sous quel surnom l’Empire ottoman est-il désigné au XIXe siècle ?', 'mcq', '["L’homme malade de l’Europe","Le géant endormi","La Sublime Porte déchue","Le colosse aux pieds d’argile"]'::jsonb, 0, 'La formule est attribuée au tsar Nicolas Ier.', 1),
    ('f8c67559-412c-5aff-9a85-ee9affe7e022'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Quel événement de 1683 marque un tournant pour l’Empire ottoman ?', 'mcq', '["L’échec du siège de Vienne","La prise de Constantinople","La bataille de Lépante","Le traité de Sèvres"]'::jsonb, 0, 'Il ouvre une série de défaites face à l’Autriche et à la Russie.', 2),
    ('ac0c4595-75a7-57da-84ff-748f4f818c03'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Que sont les capitulations dans l’Empire ottoman ?', 'mcq', '["Des privilèges commerciaux et judiciaires accordés aux Européens","Des redditions militaires","Des traités de paix","Des lois religieuses"]'::jsonb, 0, 'Elles témoignent de la dépendance croissante envers l’Europe.', 3),
    ('99002adb-ecaa-5a51-bd78-0894bd5f60e5'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Qu’a créé l’endettement ottoman en 1881 ?', 'mcq', '["L’Administration de la Dette publique ottomane, qui place les recettes sous contrôle étranger","Une banque centrale indépendante","Une monnaie commune","Un impôt européen"]'::jsonb, 0, 'La souveraineté financière de l’Empire y est entamée.', 4),
    ('b580d3e6-e60e-52be-894f-1d7c31ec3336'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Que perd la Russie avec la disparition de l’URSS en 1991 ?', 'mcq', '["Près de la moitié de sa population, un quart de son territoire et son statut de superpuissance","Uniquement ses colonies","Son siège à l’ONU","Son arsenal nucléaire"]'::jsonb, 0, 'Les années 1990 sont celles de l’effondrement économique.', 5),
    ('d0ab4971-b51b-521a-a30c-9d7dc59c9fcc'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Quelle ressource la Russie utilise-t-elle comme instrument diplomatique après 2000 ?', 'mcq', '["La rente énergétique, gaz et pétrole","Les terres rares","Les céréales uniquement","Le tourisme"]'::jsonb, 0, 'Elle accompagne la reprise en main de l’État et la modernisation militaire.', 6),
    ('dcf54275-4e9f-5e95-a8b5-8acd41a42f2e'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Les réformes des Tanzimat ont renversé le déclin ottoman.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles n’ont pas empêché l’issue de 1918 et la fin de l’Empire.', 7),
    ('f7b05e11-8671-56ba-ac3d-3c5c6bf8c5b3'::uuid, '799abb76-8014-5ad4-9b03-0706c5cd9895'::uuid, 'Quelle différence de stratégie oppose les deux trajectoires ?', 'mcq', '["L’Empire ottoman a cherché à se réformer, la Russie à se réaffirmer par la force","Les deux ont choisi la réforme","Les deux ont choisi l’isolement","Aucune différence notable"]'::jsonb, 0, 'Le jalon invite à comparer ces réponses au déclin.', 8),
    ('dfa2e181-5c91-5b5e-9785-236612efc523'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Quel exemple montre qu’une puissance moyenne peut réussir par la culture ?', 'mcq', '["La vague coréenne, musique et séries","Hollywood","Le cinéma français des années 1930","Les studios indiens"]'::jsonb, 0, 'Le soft power n’est pas réservé aux plus grandes puissances.', 1),
    ('4e7d3a30-3425-58d6-9137-340400ccadb2'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Pourquoi la langue est-elle un instrument de puissance ?', 'mcq', '["Elle ouvre des marchés et structure les normes et les réseaux","Elle est plus facile à apprendre","Elle permet la traduction automatique","Elle réduit les coûts militaires"]'::jsonb, 0, 'L’anglais domine la publication scientifique.', 2),
    ('f437c1a7-ed67-50df-abaf-1729b7080988'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Quel détroit est stratégique pour le transit du pétrole ?', 'mcq', '["Le détroit d’Ormuz","Le détroit de Gibraltar","Le canal de Panama","Le Bosphore"]'::jsonb, 0, 'Malacca, lui, est vital pour le commerce asiatique.', 3),
    ('56f35b2a-a88d-5d23-be1b-720e1d86b7b7'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Que transportent les câbles sous-marins ?', 'mcq', '["L’essentiel des données mondiales","Le pétrole","Le gaz naturel","L’électricité uniquement"]'::jsonb, 0, 'Leur vulnérabilité est devenue un sujet de sécurité.', 4),
    ('56d9e597-16f3-5520-a11c-9f78663a03af'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Qu’est-ce que les nouvelles routes de la soie ?', 'mcq', '["Un programme chinois d’investissements en infrastructures créant des liens durables","Un accord commercial européen","Une route touristique","Un traité de libre-échange américain"]'::jsonb, 0, 'Elles créent parfois des dépendances par la dette.', 5),
    ('78e9c50d-473f-52d5-a5a3-874965c8baa8'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Fixer une norme technique internationale est un enjeu de puissance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Celui qui la fixe impose ses choix à tous ceux qui veulent vendre.', 6),
    ('33fb294e-96a0-583e-a48e-6d717c83caa4'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Pourquoi accueillir des étudiants étrangers est-il un investissement d’influence ?', 'mcq', '["Ils repartent avec un réseau et une familiarité durables","Ils paient des droits d’inscription élevés","Ils restent définitivement","Ils remplacent la diplomatie"]'::jsonb, 0, 'C’est l’un des leviers d’influence les plus rentables.', 7),
    ('1f9d15c7-27ab-526a-9276-b463ec999fac'::uuid, 'a928d6ba-7c47-516f-8ae5-2ab38b6d70a6'::uuid, 'Une dépendance créée par la puissance indirecte est toujours à sens unique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une dépendance mutuelle contraint les deux parties.', 8),
    ('4b04f52a-0a33-56d7-9464-f64f141337ef'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Pourquoi qualifie-t-on la puissance américaine de « complète » ?', 'mcq', '["Elle est présente sur tous les registres à la fois","Elle est militaire uniquement","Elle est incontestée","Elle est la plus ancienne"]'::jsonb, 0, 'Militaire, économique, monétaire, culturelle et scientifique.', 1),
    ('590408a1-48cd-5858-a200-ff46a210f3a7'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Quel avantage le dollar confère-t-il aux États-Unis ?', 'mcq', '["Financer leurs déficits et faire de la sanction financière une arme","Réduire leur dette automatiquement","Fixer les prix du pétrole","Éviter toute inflation"]'::jsonb, 0, 'L’extraterritorialité du droit américain en découle.', 2),
    ('b7fb3564-7271-5103-a53a-adfabccd7d55'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Comment se compare le budget de défense américain aux autres ?', 'mcq', '["Il dépasse celui des dix pays suivants réunis","Il est le deuxième mondial","Il équivaut à celui de la Chine","Il est en forte baisse"]'::jsonb, 0, 'Avec environ 750 bases dans quelque 80 pays.', 3),
    ('8f794bf1-f10d-5864-b1bd-ebb9e75bdbbc'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Quelle est la principale contestation externe de la primauté américaine ?', 'mcq', '["La Chine, sur presque tous les registres","Le Brésil","L’Union européenne seule","Le Japon"]'::jsonb, 0, 'Commerce, technologies, monnaie et influence régionale.', 4),
    ('99b14b0c-6190-5270-8055-8f5755a166ed'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'La multipolarité signifie que tous les pôles sont d’égale puissance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les États-Unis restent la seule puissance réunissant tous les attributs.', 5),
    ('663ada3c-b35f-528d-a7ef-d363d2f22a3f'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Quelle limite interne pèse sur la politique étrangère américaine ?', 'mcq', '["La polarisation politique, qui la rend moins prévisible","L’absence d’armée permanente","Le manque d’universités","L’absence de monnaie nationale"]'::jsonb, 0, 'Elle varie fortement d’une administration à l’autre.', 6),
    ('0c6ed747-c9be-52ca-b9c1-6721118b9da2'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Les guerres d’Irak et d’Afghanistan ont nourri un débat sur l’engagement extérieur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Entre interventionnisme et retrait, l’opinion américaine reste divisée.', 7),
    ('b2048ace-38b7-5f3d-91a0-b11df41cd487'::uuid, 'a680bbc6-98b7-5747-8b5a-3437f2de4ae2'::uuid, 'Quel rôle les États-Unis ont-ils joué dans l’ordre international issu de 1945 ?', 'mcq', '["Ils en sont le principal architecte, et parfois le contestataire","Ils y ont toujours été extérieurs","Ils l’ont subi","Ils n’ont contribué qu’à l’ONU"]'::jsonb, 0, 'Ils s’en écartent occasionnellement au nom de leurs intérêts.', 8),
    ('63a0ce3a-d36d-5e15-bed3-cb3bf9daaf7c'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Qu’est-ce qu’une frontière ?', 'mcq', '["La limite d’un territoire sur lequel s’exerce une souveraineté","Un obstacle naturel","Une zone militaire","Une ligne de démarcation provisoire"]'::jsonb, 0, 'Elle est à la fois ligne, institution juridique et fait social.', 1),
    ('b11407db-2191-5952-9d62-546bdacbc679'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Pourquoi l’expression « frontière naturelle » est-elle trompeuse ?', 'mcq', '["Parce qu’un fleuve unit souvent les rives plus qu’il ne les sépare","Parce que les fleuves changent de cours","Parce que la nature n’existe pas","Parce que les montagnes sont franchissables"]'::jsonb, 0, 'Une frontière est toujours une construction politique.', 2),
    ('96519109-9347-5557-ae98-1eec6b8188de'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Quelle est l’étendue de la zone économique exclusive selon la convention de Montego Bay ?', 'mcq', '["200 milles marins","12 milles marins","50 milles marins","500 milles marins"]'::jsonb, 0, 'La mer territoriale, elle, s’étend sur 12 milles.', 3),
    ('cb92b95f-1e54-50e2-819d-c12346c903c2'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Pourquoi les îles les plus modestes ont-elles un intérêt stratégique ?', 'mcq', '["Parce qu’elles ouvrent droit à une zone économique exclusive","Parce qu’elles abritent des bases","Parce qu’elles sont peuplées","Parce qu’elles produisent du pétrole"]'::jsonb, 0, 'Le droit de la mer transforme un rocher en ressource.', 4),
    ('9a4f22b3-bb95-56e4-9229-75a4a8b09c6d'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'La mondialisation a fait disparaître les frontières.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle les DIFFÉRENCIE : ouvertes aux capitaux, sélectives pour les personnes.', 5),
    ('d2141684-c374-569f-992c-55fd11f324a2'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Combien de murs frontaliers comptait-on à la chute du mur de Berlin ?', 'mcq', '["Moins d’une dizaine","Plusieurs dizaines","Aucun","Plus de cent"]'::jsonb, 0, 'Il y en a aujourd’hui plusieurs dizaines.', 6),
    ('b8bb4124-f1df-548e-8e3f-98aca37b5ed2'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Que sont les frontières géométriques ?', 'mcq', '["Des frontières tracées à la règle, souvent héritées de partages coloniaux","Des frontières suivant un relief","Des frontières maritimes","Des frontières mobiles"]'::jsonb, 0, 'Elles sont fréquentes en Afrique et en Amérique du Nord.', 7),
    ('f8127461-db7c-5f64-8c8d-a688b55421f9'::uuid, '705abefc-841a-5369-8a80-721f07414499'::uuid, 'Certaines frontières sont des zones plutôt que des lignes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Marges et confins sont des espaces de transition où l’autorité s’estompe.', 8),
    ('ce1e2240-6023-5904-8a84-9672486684f1'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Que posent les traités de Westphalie en 1648 ?', 'mcq', '["Le principe de souveraineté territoriale exclusive","Le droit des peuples à disposer d’eux-mêmes","L’abolition des frontières","La liberté des mers"]'::jsonb, 0, 'C’est l’acte de naissance du système international moderne.', 1),
    ('4caa8f80-dd52-5e07-aeeb-3326ecf8ffe2'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Qu’organise la conférence de Berlin de 1884-1885 ?', 'mcq', '["Le partage de l’Afrique entre puissances européennes","La fin de la traite","Le tracé des frontières européennes","La création de la Société des Nations"]'::jsonb, 0, 'Sans consultation ni connaissance des réalités locales.', 2),
    ('a234445d-fe19-52a5-b14d-b0dfb56d99d7'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Que signifie le principe de l’uti possidetis juris ?', 'mcq', '["Les nouveaux États héritent des frontières coloniales","Chaque peuple choisit son État","Les frontières sont redessinées après indépendance","Le vainqueur fixe la frontière"]'::jsonb, 0, 'Assumé par l’Organisation de l’unité africaine en 1964.', 3),
    ('9e3e7ce5-e657-56ec-977b-7f51f7343fe2'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Pourquoi l’OUA a-t-elle conservé des frontières reconnues arbitraires ?', 'mcq', '["Parce que les rouvrir toutes provoquerait des guerres en chaîne","Parce qu’elles étaient justes","Parce que l’ONU l’imposait","Parce qu’elles suivaient les peuplements"]'::jsonb, 0, 'Un arbitrage de la stabilité contre la justice du tracé.', 4),
    ('d686f00d-a90e-5ad4-8313-79a97b265d9a'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Le droit des peuples à disposer d’eux-mêmes a pu être appliqué à la lettre en 1919.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les peuplements mêlés ont laissé partout des minorités.', 5),
    ('8ee17a98-d08e-5685-be62-16410f0ebdeb'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Quel exemple de partition par référendum le thème retient-il ?', 'mcq', '["Le Soudan du Sud en 2011","Chypre en 1974","Le Cachemire en 1947","La Crimée en 2014"]'::jsonb, 0, 'L’autodétermination y a été organisée et reconnue.', 6),
    ('e283a31d-a9ac-54a6-bd9e-668b4033e04e'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Qu’est-ce qui rend souvent un tracé frontalier conflictuel ?', 'mcq', '["La présence de ressources, une population partagée ou une valeur symbolique","La longueur de la frontière","Le climat","Le relief plat"]'::jsonb, 0, 'L’absence de reconnaissance internationale aggrave le différend.', 7),
    ('1e90162b-f7b6-5e75-aa8f-a97e250fe8ce'::uuid, 'ba3bded1-caa3-5c50-b70c-4d99f01d05ba'::uuid, 'Une frontière n’existe pleinement que si les autres États l’acceptent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une relation, pas seulement un tracé.', 8),
    ('5861b840-983a-5ecf-89d5-a11fe1991731'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Qu’est-ce qu’un État de facto ?', 'mcq', '["Une entité qui contrôle un territoire sans être reconnue internationalement","Un État fédéral","Un État sans constitution","Un territoire sous mandat de l’ONU"]'::jsonb, 0, 'Somaliland, Transnistrie et Ossétie du Sud en sont des exemples.', 1),
    ('c327d313-a41c-5b55-8994-af6148310d14'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'La reconnaissance d’un État est-elle un simple constat ?', 'mcq', '["Non, c’est un acte politique","Oui, elle est automatique","Oui, elle relève de l’ONU seule","Non, elle est juridiquement obligatoire"]'::jsonb, 0, 'On reconnaît aussi en fonction de ses propres contentieux internes.', 2),
    ('2d00685f-1d8b-55e4-a9ca-56b78ba8954b'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Que supprime l’espace Schengen ?', 'mcq', '["Les contrôles aux frontières intérieures","Toutes les frontières européennes","Les droits de douane mondiaux","Les contrôles à la frontière extérieure"]'::jsonb, 0, 'La frontière extérieure commune est au contraire renforcée.', 3),
    ('9eba0bea-3431-5b5c-9d7b-4eb5e8106a53'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Ouvrir les frontières intérieures suppose de fermer davantage à l’extérieur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Schengen implique bases de données communes et agence de garde-frontières.', 4),
    ('3f068eb9-43fe-54e7-9160-1977256b7158'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Qu’est-ce que la coopération transfrontalière ?', 'mcq', '["Des dispositifs communs entre territoires voisins de part et d’autre d’une frontière","Un traité militaire","Un accord de libre-échange mondial","Une union monétaire"]'::jsonb, 0, 'Eurorégions, bassins de vie partagés, travailleurs frontaliers.', 5),
    ('48c6213e-79f0-5827-aaf2-13f1509e2f60'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Qu’a montré la pandémie du point de vue des frontières ?', 'mcq', '["La rapidité avec laquelle des frontières crues effacées se referment","Que les frontières avaient disparu","Que Schengen était irréversible","Que les contrôles étaient inutiles"]'::jsonb, 0, 'Le retour des frontières est aussi net que leur ouverture.', 6),
    ('b316967a-1009-5bb6-a16f-854e0a83b764'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Pourquoi le cas du Kosovo est-il instructif ?', 'mcq', '["Sa reconnaissance dépend des contentieux internes de chaque État","Il n’est reconnu par personne","Il est reconnu par tous","Il n’a pas de territoire"]'::jsonb, 0, 'Reconnu par une centaine d’États, refusé par d’autres.', 7),
    ('aa7f7d20-1f24-50af-8724-ac32549b7136'::uuid, 'f77198c6-d43a-5d03-9941-c9b983c4c8ca'::uuid, 'Les flux de données et de capitaux respectent les frontières étatiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils les ignorent largement, d’où les questions de régulation et de fiscalité.', 8),
    ('d3c9d636-a3c4-5933-af9c-8c89e28c080f'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Qu’est-ce que l’effet frontière ?', 'mcq', '["L’activité créée par l’écart de législation, de prix ou de salaires entre deux pays","La fermeture d’une frontière","La longueur d’une frontière","Le contrôle douanier"]'::jsonb, 0, 'Commerces frontaliers et travail frontalier en découlent.', 1),
    ('758c0ee7-7583-53d7-96e4-692dbef405f1'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Que sont les maquiladoras ?', 'mcq', '["Des usines d’assemblage installées le long de la frontière mexicaine","Des marchés transfrontaliers","Des postes de douane","Des zones agricoles"]'::jsonb, 0, 'Elles combinent salaires mexicains et accès au marché américain.', 2),
    ('a2e43d00-f0ec-5e6b-9dfd-fd520b73842c'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Quelle difficulté typique rencontrent les régions transfrontalières ?', 'mcq', '["Des régimes fiscaux et sociaux différents et des diplômes non reconnus","L’absence de population","Le manque de transports uniquement","L’absence de langue commune systématique"]'::jsonb, 0, 'Les secours ne peuvent parfois pas franchir la ligne.', 3),
    ('d8502638-b221-574a-9f81-8f82ea03dace'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Si les deux côtés d’une frontière étaient identiques, l’activité frontalière disparaîtrait.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’asymétrie qui crée les flux et l’intérêt à traverser.', 4),
    ('8294d48f-843c-5a72-afb5-a8ccbe6f4959'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Quel espace transfrontalier associe le Danemark et la Suède ?', 'mcq', '["L’Öresund","La Grande Région","Le Rhin supérieur","Le Benelux"]'::jsonb, 0, 'Un bassin de vie intégré, doté de transports communs.', 5),
    ('507d8639-f300-5eb7-9b5c-a1ef32278794'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Quelle ville suisse se trouve au contact de trois pays ?', 'mcq', '["Bâle","Genève","Zurich","Lausanne"]'::jsonb, 0, 'Genève, elle, a un bassin d’emploi qui déborde en France.', 6),
    ('cd0974e3-7b92-545e-8a7a-59dde0f1a7c5'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Les économies illégales vivent aussi de l’écart entre deux régimes juridiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contrebande et trafics prospèrent sur la différence de législation.', 7),
    ('0cd1996b-61ea-5b9c-a1ee-7eac94c92b8e'::uuid, 'cce18aff-0c27-52e7-94da-f4c6b39ad7b7'::uuid, 'Qui gère concrètement un espace frontalier ?', 'mcq', '["Plusieurs niveaux d’acteurs, du local au national","Le seul pouvoir central","Les seules douanes","Une agence internationale"]'::jsonb, 0, 'C’est un espace de négociation permanente.', 8),
    ('99b0cefd-6dae-54e5-b69f-843379b72fe7'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Que prévoient les accords de Dublin ?', 'mcq', '["Le premier pays d’entrée est responsable de l’examen de la demande d’asile","La répartition égale des demandeurs entre États","La libre circulation des demandeurs","La compétence exclusive de Frontex"]'::jsonb, 0, 'D’où la charge concentrée sur les pays méditerranéens.', 1),
    ('58410d69-2ff4-560b-b051-d841d193cafd'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Quel est le rôle de Frontex ?', 'mcq', '["Appuyer les États dans la surveillance de la frontière extérieure","Instruire les demandes d’asile","Contrôler les frontières intérieures","Négocier les traités"]'::jsonb, 0, 'Créée en 2004, devenue agence de garde-frontières et de garde-côtes.', 2),
    ('d5f06e98-acb1-5170-87bd-5b894f262af1'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Les mécanismes de répartition des demandeurs d’asile ont durablement fonctionné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque crise rouvre le conflit entre solidarité et souveraineté nationale.', 3),
    ('e77af8dc-e66d-515c-b3f6-3a667aeacf51'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Quelle différence entre un demandeur d’asile et un migrant économique ?', 'mcq', '["Le premier sollicite une protection au titre du droit international, le second relève des politiques nationales","Aucune, ce sont des synonymes","Le premier vient toujours d’Afrique","Le second bénéficie de plus de droits"]'::jsonb, 0, 'Les catégories se recouvrent dans les faits, mais pas en droit.', 4),
    ('6bbe48ff-297d-5eea-9c7a-b6a6c26b5447'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Sur quel texte repose le droit d’asile ?', 'mcq', '["La convention de Genève de 1951","Le traité de Rome","Les accords de Schengen","Le pacte de 2024"]'::jsonb, 0, 'C’est un droit individuel protégé par le droit international.', 5),
    ('b109d113-b403-5c91-a57a-5767ef94910e'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Combien de personnes sont arrivées dans l’Union en 2015 ?', 'mcq', '["Plus d’un million","Environ cent mille","Environ dix millions","Moins de cinquante mille"]'::jsonb, 0, 'Fuyant principalement la Syrie, l’Afghanistan et l’Érythrée.', 6),
    ('5c2d4a98-c95e-514f-bd37-3add33c3ceb6'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'Quelle est la route migratoire la plus meurtrière du monde ?', 'mcq', '["La Méditerranée","La frontière américano-mexicaine","La Manche","La mer Égée seule"]'::jsonb, 0, 'Plusieurs dizaines de milliers de disparus depuis 2014.', 7),
    ('c34adb7f-3b3b-590a-8cff-7530f052d64e'::uuid, 'f1e48f65-9aed-580b-b4fd-be221f9884fa'::uuid, 'L’espace Schengen ne comprend que des États membres de l’Union européenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il compte 27 pays, dont quatre qui ne sont pas membres de l’Union.', 8),
    ('c2ba598a-0956-58a9-bb37-2a245332af3b'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Vers quelle date Gutenberg met-il au point l’imprimerie à caractères mobiles ?', 'mcq', '["Vers 1450","Vers 1350","Vers 1550","Vers 1650"]'::jsonb, 0, 'Ce qu’un copiste mettait un an à produire s’imprime en centaines d’exemplaires.', 1),
    ('c96833f5-2979-5855-a956-1e47ae4a4b35'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Quel mouvement religieux profite le plus de l’imprimerie naissante ?', 'mcq', '["La Réforme protestante","La Contre-Réforme","Le jansénisme","Le gallicanisme"]'::jsonb, 0, 'Les thèses de Luther circulent en quelques semaines dans tout l’Empire.', 2),
    ('c5fa6999-ff11-5a5b-a73d-95c1e0e239ad'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Quel périodique Théophraste Renaudot fonde-t-il en 1631 ?', 'mcq', '["La Gazette","Le Mercure","Le Petit Journal","Le Moniteur"]'::jsonb, 0, 'Première publication périodique française, proche du pouvoir.', 3),
    ('2d018f61-2fbf-5318-b47c-81adebb261f6'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Que fait la loi de 1881 sur la presse ?', 'mcq', '["Elle supprime l’autorisation préalable et instaure une responsabilité a posteriori","Elle rétablit la censure","Elle nationalise les journaux","Elle crée un ministère de l’Information"]'::jsonb, 0, 'Elle est encore en vigueur aujourd’hui.', 4),
    ('a5ae7e1f-17e2-5084-8020-665273d1a2d2'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Quelles conditions permettent l’essor de la presse à grand tirage ?', 'mcq', '["Rotatives, papier bon marché, alphabétisation, chemin de fer et publicité","La seule invention de l’imprimerie","La suppression des impôts","Le développement de la radio"]'::jsonb, 0, 'La publicité permet de vendre le journal sous son coût.', 5),
    ('0e9453dd-f870-5737-b2f8-4bdbe50d0fcf'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'L’imprimé a permis de stabiliser les savoirs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un texte identique partout rend possible la comparaison et la critique.', 6),
    ('6da4f515-c8e1-58fb-855f-34379e17b5b5'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Quel effet le financement publicitaire a-t-il sur le contenu d’un journal ?', 'mcq', '["Il le rend dépendant de l’audience, donc du fait divers et du sensationnel","Il garantit son indépendance","Il supprime les rubriques politiques","Il n’a aucun effet"]'::jsonb, 0, 'Le modèle économique pèse sur la ligne éditoriale.', 7),
    ('4fb3a48c-f03c-52b2-8697-01ac270db9f3'::uuid, '588cc3c7-7b8a-59a6-8011-ed21c93a8ce3'::uuid, 'Quel quotidien dépasse le million d’exemplaires à la fin du XIXe siècle ?', 'mcq', '["Le Petit Journal","La Gazette","Le Figaro","L’Aurore"]'::jsonb, 0, 'La presse devient le premier média de masse de l’histoire.', 8),
    ('5eaf07b0-d2b7-573a-afc7-46c06ef07fc0'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel avantage la radio présente-t-elle sur la presse écrite ?', 'mcq', '["L’immédiateté, et l’accès de ceux que l’écrit n’atteignait pas","Une meilleure précision","Un coût de production supérieur","Une plus grande liberté légale"]'::jsonb, 0, 'Elle touche les analphabètes et crée un lien de proximité.', 1),
    ('c1ad7a4a-e1d5-53fb-a162-8ac0a727f0b4'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel discours du 18 juin 1940 illustre le rôle politique de la radio ?', 'mcq', '["L’Appel du général de Gaulle sur la BBC","Une causerie de Roosevelt","Un discours de Churchill au Parlement","Une allocution de Pétain"]'::jsonb, 0, 'Radio Londres et ses messages personnels joueront un rôle majeur.', 2),
    ('de7e02a0-c6b3-550a-a703-48ddbaa9c566'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Jusqu’à quand la radiodiffusion est-elle un monopole d’État en France ?', 'mcq', '["Jusqu’en 1982","Jusqu’en 1968","Jusqu’en 1974","Jusqu’en 1990"]'::jsonb, 0, 'Une autorité de régulation est alors créée, avant la privatisation de TF1 en 1987.', 3),
    ('c9fce413-e960-5ab9-8500-b979072d49bf'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Que révèle le débat télévisé Kennedy-Nixon de 1960 ?', 'mcq', '["Que l’apparence à l’écran peut peser plus que les arguments","Que la télévision est un média secondaire","Que le direct est impossible","Que les débats sont sans effet"]'::jsonb, 0, 'Les auditeurs radio et les téléspectateurs n’ont pas désigné le même vainqueur.', 4),
    ('26ed4e00-6df0-5b6e-a0e9-a98e0324529c'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Les radios libres ont été autorisées en France en 1981.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après des années d’émissions clandestines.', 5),
    ('9b67ef18-4852-595e-911c-1031a582a660'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel conflit marque le passage à l’information en flux continu ?', 'mcq', '["La guerre du Golfe de 1991","La guerre du Vietnam","La guerre d’Algérie","La guerre des Malouines"]'::jsonb, 0, 'L’image en direct s’impose au moment où elle est le moins vérifiée.', 6),
    ('9b370ba4-fd08-52c7-b1e6-ff07c37847a8'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Quel effet la télévision a-t-elle eu sur la vie politique ?', 'mcq', '["Une personnalisation croissante, centrée sur la présence à l’écran","Un renforcement des partis","Une hausse de la participation électorale","Une disparition des débats"]'::jsonb, 0, 'Le format impose ses contraintes au contenu.', 7),
    ('1cd1313d-5ded-5a21-8dac-78d6f813377d'::uuid, '2d14a592-9307-5bf6-bb04-0b487053af5c'::uuid, 'Le coût élevé des médias de masse pose la question de leur propriété.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La concentration met en jeu l’indépendance des rédactions.', 8),
    ('7d43e6c8-ade9-55bb-89dc-119b2d067386'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'De quel projet Internet est-il issu ?', 'mcq', '["ARPANET, un réseau de recherche militaire américain","Un projet commercial d’IBM","Un programme européen","Une initiative de l’ONU"]'::jsonb, 0, 'Réseau décentralisé, conçu pour survivre à la destruction d’un nœud.', 1),
    ('11ba661b-51ce-5c95-89ca-05f9a222c487'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Qui invente le World Wide Web au CERN ?', 'mcq', '["Tim Berners-Lee","Vinton Cerf","Steve Jobs","Alan Turing"]'::jsonb, 0, 'Liens hypertextes, adresses et navigateur, entre 1989 et 1991.', 2),
    ('d175ec4c-61cd-550a-a011-8b30023fd720'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Qu’est-ce qu’une bulle de filtres ?', 'mcq', '["Une exposition principalement à ce qui confirme ses convictions","Un dispositif de sécurité informatique","Un filtre publicitaire","Un moteur de recherche spécialisé"]'::jsonb, 0, 'Elle raréfie la contradiction et renforce les convictions.', 3),
    ('25baf09e-a230-5d9d-863e-a29643eb8921'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Quel est le principal enjeu de l’information à l’ère d’Internet ?', 'mcq', '["Sa hiérarchisation et sa vérification, plus que son accès","Son coût d’achat","Sa vitesse de transmission","Sa longueur"]'::jsonb, 0, 'L’accès est devenu presque illimité.', 4),
    ('2e916111-3ac0-5c23-a4d7-3b80cd9f9bcb'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Sur quoi repose la gratuité apparente des grandes plateformes ?', 'mcq', '["Sur la publicité, donc sur l’attention et les données","Sur des subventions publiques","Sur le mécénat","Sur les abonnements"]'::jsonb, 0, 'Le service est financé, mais pas par celui qui l’utilise.', 5),
    ('bb662983-1a1a-5bd8-a730-3e30021a30b3'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Ce qui circule le plus sur les réseaux est ce qui a été le mieux vérifié.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est ce qui suscite le plus de réactions qui circule.', 6),
    ('5deabc22-eaaa-5bd5-a4f3-de6157738e01'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Qu’est-ce que l’infobésité ?', 'mcq', '["Une abondance d’informations qui rend le tri plus difficile que la recherche","Un excès de publicité","Une saturation des réseaux","Un défaut de mémoire des serveurs"]'::jsonb, 0, 'Le problème s’est déplacé de la rareté vers le tri.', 7),
    ('868b0666-c98b-5e48-a61a-87040b984d33'::uuid, '6d2f712c-649d-54ac-a89b-9b904907c8f5'::uuid, 'Quelle est la véritable fracture numérique ?', 'mcq', '["La capacité à user du réseau de façon critique, au-delà de l’accès matériel","La vitesse de connexion","Le prix des appareils","La langue des contenus"]'::jsonb, 0, 'L’accès matériel ne suffit pas à réduire l’inégalité.', 8),
    ('e3f73bb7-ad56-5018-b8f6-9b92aad2a295'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'De quoi le capitaine Dreyfus est-il accusé en 1894 ?', 'mcq', '["D’avoir livré des documents militaires à l’Allemagne","D’avoir déserté","D’avoir comploté contre la République","D’avoir détourné des fonds"]'::jsonb, 0, 'Il est condamné sur la foi d’une pièce mince et d’une expertise contestée.', 1),
    ('ce147de2-10d9-59b3-af4f-d890be3946a8'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Dans quel journal Zola publie-t-il « J’accuse… ! » ?', 'mcq', '["L’Aurore","Le Figaro","La Libre Parole","Le Petit Journal"]'::jsonb, 0, 'Le 13 janvier 1898, à la une, avec un titre trouvé par Clemenceau.', 2),
    ('4b1dd291-3f6e-55ab-b02c-afd1a90c6c2b'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Pourquoi Zola cherche-t-il à être poursuivi en diffamation ?', 'mcq', '["Pour obtenir un débat contradictoire public","Pour devenir célèbre","Pour éviter la prison","Par erreur juridique"]'::jsonb, 0, 'Le procès devait permettre de discuter publiquement des preuves.', 3),
    ('ac007629-27c5-5ff2-9e2a-d61a2d002d6a'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Qui découvre en 1896 que le véritable auteur du bordereau est Esterhazy ?', 'mcq', '["Le colonel Picquart","Émile Zola","Georges Clemenceau","Le capitaine Dreyfus lui-même"]'::jsonb, 0, 'L’état-major étouffe alors l’affaire.', 4),
    ('3b330a87-8685-5128-9b37-2e33bfac9f48'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Quel groupe social apparaît avec l’affaire Dreyfus ?', 'mcq', '["Les intellectuels, au sens actuel du mot","Les journalistes professionnels","Les syndicalistes","Les fonctionnaires"]'::jsonb, 0, 'Le « Manifeste des intellectuels » de janvier 1898 fixe l’usage du mot.', 5),
    ('7afc112b-6627-51d3-a98d-2f4ea0644969'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'La presse a joué un rôle uniquement favorable à Dreyfus.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La presse antidreyfusarde a déversé un antisémitisme violent et fabriqué de fausses preuves.', 6),
    ('3d938f56-7f99-52fe-9053-5be238d9afa9'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'En quelle année Dreyfus est-il réhabilité ?', 'mcq', '["1906","1899","1898","1914"]'::jsonb, 0, 'Il est gracié dès 1899, mais la réhabilitation est plus tardive.', 7),
    ('e59dd058-984e-5e36-a3bc-7ffaa7ca1b88'::uuid, '5773ea8a-001b-5d58-8070-835f392c6820'::uuid, 'Que montre l’affaire sur la liberté de la presse ?', 'mcq', '["Elle a permis la calomnie et son démenti : elle est la condition de la correction de l’erreur","Qu’elle doit être limitée","Qu’elle est sans effet politique","Qu’elle garantit la vérité"]'::jsonb, 0, 'Elle n’est pas un instrument neutre, mais elle est indispensable.', 8),
    ('e7ce714e-3c7c-5a2c-ba46-63e62b6a7e14'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Que proclame l’article 11 de la Déclaration de 1789 ?', 'mcq', '["La libre communication des pensées et des opinions","La liberté de réunion","Le droit de vote","La liberté de culte"]'::jsonb, 0, 'En réservant la répression des abus définis par la loi.', 1),
    ('ff20f15e-659e-5358-9fcb-f4bc2a4eb110'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Que supprime la loi de 1881 ?', 'mcq', '["L’autorisation préalable et le cautionnement","La responsabilité des journalistes","Le droit de réponse","Le secret des sources"]'::jsonb, 0, 'Elle instaure une responsabilité a posteriori devant les tribunaux.', 2),
    ('84f5289c-c639-5163-9c9c-7988f9bcaa18'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Quel article de la Déclaration universelle de 1948 porte sur l’information ?', 'mcq', '["L’article 19","L’article 11","L’article 1er","L’article 10"]'::jsonb, 0, 'Chercher, recevoir et répandre les informations sans considération de frontières.', 3),
    ('8f6c1bd7-83c6-5eda-8002-cb3760e7a402'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Pourquoi la protection des sources est-elle essentielle au journalisme ?', 'mcq', '["Sans elle, personne n’accepte de parler à un journaliste","Elle protège les journalistes des procès","Elle garantit leur rémunération","Elle accélère la publication"]'::jsonb, 0, 'Elle est reconnue par la loi française depuis 2010.', 4),
    ('a984f14a-5d2e-5d73-b9c6-e218c718c958'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'La liberté d’information est une liberté absolue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Diffamation, incitation à la haine, vie privée et secret de la défense la bornent.', 5),
    ('1bdcaecc-fb3e-506e-bbb6-fecaea060ad9'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Qui doit décider des limites à la liberté d’information ?', 'mcq', '["Le juge, et non l’administration","Le gouvernement","Les rédactions elles-mêmes","Une commission de censure"]'::jsonb, 0, 'Ces limites sont exactement celles qu’un pouvoir invoque pour restreindre.', 6),
    ('0c0db7d4-244c-5c7a-9b56-95fa4cfc6d0e'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'Qu’est-ce qu’une procédure-bâillon ?', 'mcq', '["Une action en justice destinée à épuiser un journaliste plutôt qu’à obtenir gain de cause","Une saisie de journaux","Une amende administrative","Une interdiction de publication"]'::jsonb, 0, 'Elle vise l’investigation par l’usure financière et morale.', 7),
    ('a9e3b14b-197d-5f0d-83a6-51b298d5795c'::uuid, '07c757c6-a089-553d-8eb4-b1bc4be87856'::uuid, 'La liberté de l’information se mesure au contenu des textes de loi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle se mesure à ce qu’il est effectivement possible de publier.', 8),
    ('4361f4af-f336-5213-9f09-6740b8f7f18f'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Qu’appelle-t-on le « bourrage de crâne » pendant la Grande Guerre ?', 'mcq', '["La propagande minimisant les pertes et promettant une victoire proche","La censure des lettres de soldats","Un entraînement militaire","Une méthode d’interrogatoire"]'::jsonb, 0, 'Il a nourri une défiance durable des combattants envers la presse.', 1),
    ('4954beed-a092-5a02-aa06-3386e9f5bda5'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Quel trait caractérise la propagande totalitaire ?', 'mcq', '["La réécriture du passé, jusqu’à la retouche des photographies","La liberté de la presse locale","Le pluralisme des sources","L’absence de radio"]'::jsonb, 0, 'Contrôler le passé, c’est contrôler l’avenir, écrit Orwell.', 2),
    ('17debf05-6696-55df-9a1e-085c61f2a377'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Quels journaux clandestins paraissent sous l’Occupation ?', 'mcq', '["Combat, Libération, Défense de la France","Le Figaro et Le Monde","La Gazette et Le Mercure","L’Aurore et Le Petit Journal"]'::jsonb, 0, 'Radio Londres diffuse en parallèle depuis l’extérieur.', 3),
    ('58baa1eb-fb70-5829-9c91-2e2f44de8747'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Qu’était Radio-Paris sous l’Occupation ?', 'mcq', '["Une radio contrôlée par l’occupant allemand","Une radio de la Résistance","Une radio britannique","Une radio libre"]'::jsonb, 0, 'D’où la chanson « Radio-Paris ment ».', 4),
    ('7433be49-8d1d-5c4b-99f8-cc4792c38059'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Que sont les Pentagon Papers ?', 'mcq', '["Des documents classifiés sur la guerre du Vietnam publiés en 1971","Les archives du Watergate","Un rapport de l’ONU","Un plan militaire soviétique"]'::jsonb, 0, 'Leur publication a été tentée d’être empêchée par le gouvernement.', 5),
    ('dc0a6e61-0af2-534f-819a-b03d8de1b5fc'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Le Watergate a conduit à la démission du président Nixon.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’enquête du Washington Post a établi le journalisme comme contre-pouvoir.', 6),
    ('11c53538-70d6-51b3-84d4-5924f5f8e9e6'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Comment les régimes de l’Est répondaient-ils aux radios occidentales ?', 'mcq', '["Par le brouillage systématique des émissions","En les autorisant librement","En les diffusant à la télévision","En les traduisant"]'::jsonb, 0, 'Les samizdats circulaient en parallèle, recopiés à la main.', 7),
    ('26a5e04c-5f1d-5fd9-8e25-da9046c99c1a'::uuid, 'a863886f-2e9a-5d74-9760-dadd09447449'::uuid, 'Les mécanismes de contrôle de l’information appartiennent au passé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Censure, contrôle par la propriété, désinformation coordonnée et surveillance persistent.', 8),
    ('c8b7ae03-346f-5ed4-a45f-4103ff1f098c'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Que distingue la doctrine des deux glaives ?', 'mcq', '["Le pouvoir spirituel de l’Église et le pouvoir temporel des princes","Le roi et l’empereur","La justice civile et la justice pénale","Le clergé régulier et le clergé séculier"]'::jsonb, 0, 'Reste à savoir lequel prime : c’est l’enjeu de toute la période.', 1),
    ('4b79ed95-d560-54bc-90e8-f83551c91c92'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Où le roi de France est-il sacré ?', 'mcq', '["À Reims","À Paris","À Saint-Denis","À Chartres"]'::jsonb, 0, 'Oint de l’huile de la Sainte Ampoule, il devient roi par la grâce de Dieu.', 2),
    ('a2bceb13-aa51-56ca-b936-26996f0ddff3'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Quel est l’enjeu de la querelle des Investitures ?', 'mcq', '["Savoir qui nomme les évêques, le pape ou l’empereur","Le tracé des frontières de l’Empire","La langue de la liturgie","Le montant de la dîme"]'::jsonb, 0, 'Les évêques sont aussi de grands seigneurs temporels.', 3),
    ('e03f723f-cb0f-58e6-a575-5c2d9f60f942'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Quel texte met fin à la querelle des Investitures en 1122 ?', 'mcq', '["Le concordat de Worms","Le concordat de Bologne","La Pragmatique Sanction","L’édit de Nantes"]'::jsonb, 0, 'Investiture spirituelle par l’Église, temporelle par l’empereur.', 4),
    ('3fc20349-b4a1-5526-8da6-66d65d94c57f'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Que donne le concordat de Bologne de 1516 au roi de France ?', 'mcq', '["La nomination des évêques","Le droit de lever la dîme","La direction des universités","Le pouvoir d’excommunier"]'::jsonb, 0, 'C’est le fondement du gallicanisme.', 5),
    ('dc88ef0a-628c-5aa4-ae22-ba6952f70c70'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Le sacre de Charlemagne en 800 crée une dépendance à sens unique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est mutuelle : l’empereur tient sa légitimité du pape, le pape sa protection de l’empereur.', 6),
    ('4bae820f-4d03-5469-a159-40fc0b52bee7'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'Quel roi de France fait arrêter le pape Boniface VIII en 1303 ?', 'mcq', '["Philippe le Bel","Saint Louis","Charles VII","François Ier"]'::jsonb, 0, 'Le roi affirme être « empereur en son royaume ».', 7),
    ('db966459-b93a-5400-aaef-4ea47631bcf1'::uuid, '3490b924-a381-5ec1-b763-9ad9e5ce2d9b'::uuid, 'L’Église médiévale disposait de sa propre justice.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle levait aussi la dîme et encadrait enseignement, hôpitaux et assistance.', 8),
    ('fe44c64f-f6b3-5106-a474-fbc73ae9f1e8'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Quel titre religieux le sultan ottoman portait-il ?', 'mcq', '["Celui de calife","Celui d’imam","Celui de patriarche","Celui de mufti"]'::jsonb, 0, 'Chef spirituel des musulmans sunnites, en plus du pouvoir temporel.', 1),
    ('54e34b2f-dcab-59b2-aa8b-4f2e5c60a6ac'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'En quelle année le califat est-il aboli en Turquie ?', 'mcq', '["1924","1923","1928","1937"]'::jsonb, 0, 'Un an après la proclamation de la République.', 2),
    ('0d5c7a62-9f2a-5c1a-bc90-7aca8e903153'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'De quel pays le code civil turc de 1926 est-il inspiré ?', 'mcq', '["La Suisse","La France","L’Allemagne","L’Italie"]'::jsonb, 0, 'Mariage civil, interdiction de la polygamie, égalité successorale.', 3),
    ('96d3c0b4-733c-52be-aa05-4023f3d0069e'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Quelle réforme de 1928 constitue une rupture culturelle majeure ?', 'mcq', '["L’adoption de l’alphabet latin","L’instauration du calendrier grégorien","La réforme vestimentaire","La fermeture des confréries"]'::jsonb, 0, 'Elle coupe d’un coup l’accès aux textes anciens.', 4),
    ('a72c3312-f388-5704-8447-c9d9a13d493f'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Le modèle kémaliste sépare-t-il l’État et la religion ?', 'mcq', '["Non, il contrôle la religion par l’État","Oui, comme en France","Non, il instaure une religion d’État","Oui, mais sans institution dédiée"]'::jsonb, 0, 'Le Diyanet nomme les imams et rédige les prêches.', 5),
    ('d1d02c25-66bd-5a47-a0f7-3bd5ddecbd4c'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Quand la laïcité est-elle inscrite dans la Constitution turque ?', 'mcq', '["En 1937","En 1923","En 1924","En 1945"]'::jsonb, 0, 'Après plus d’une décennie de réformes.', 6),
    ('5ee70097-edf8-5f04-a606-26df2ad7c03d'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'L’armée turque est longtemps intervenue au nom de l’héritage kémaliste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '1960, 1971, 1980 et 1997 : son pouvoir est fortement réduit après 2016.', 7),
    ('2bc9987f-f4a4-5170-96f4-83653aaea516'::uuid, '6c2cf768-e581-5e5a-97bb-554bd1c6ef40'::uuid, 'Que devient Sainte-Sophie en 2020 ?', 'mcq', '["Une mosquée","Un musée","Une église","Un site fermé au public"]'::jsonb, 0, 'Symbole du tournant contemporain sur la place du religieux.', 8),
    ('0e6c1587-f1ca-56e7-ad75-4669fa2a0672'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Que pose la loi française de 1905 ?', 'mcq', '["La République ne reconnaît, ne salarie ni ne subventionne aucun culte","La religion est interdite dans l’espace public","L’État nomme les ministres du culte","Une religion d’État est instituée"]'::jsonb, 0, 'Elle garantit en même temps le libre exercice des cultes.', 1),
    ('fad78f06-f307-5e3c-840c-f0994ff2452f'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quel pays perçoit un impôt ecclésiastique collecté par l’État ?', 'mcq', '["L’Allemagne","La France","Les États-Unis","La Turquie"]'::jsonb, 0, 'C’est un régime de reconnaissance des cultes.', 2),
    ('c3886746-aa7a-5588-8cf6-aeffc486fe36'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quelle distinction est centrale dans la laïcité française ?', 'mcq', '["Entre l’agent public, tenu à la neutralité, et l’usager, libre de manifester ses convictions","Entre croyants et non-croyants","Entre cultes reconnus et non reconnus","Entre lieux de culte publics et privés"]'::jsonb, 0, 'La neutralité pèse sur l’État, non sur les personnes.', 3),
    ('0ddf0fee-b639-5931-93c8-1c177230cd25'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quel régime particulier subsiste en Alsace-Moselle ?', 'mcq', '["Le régime concordataire","La séparation stricte","La religion d’État","Le contrôle étatique du culte"]'::jsonb, 0, 'Héritage de la période où ces territoires étaient allemands.', 4),
    ('8951654d-fcaf-598f-a290-0626adec7a75'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'La liberté de changer de religion est garantie partout dans le monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Protégée par les textes internationaux, elle reste refusée dans plusieurs États.', 5),
    ('c1818071-a54f-51ef-a98e-f83459679c4c'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Le Saint-Siège est un sujet de droit international.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des acteurs religieux transnationaux du système international.', 6),
    ('c3118b5f-8c82-55ea-a7e1-24aa5196476a'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Comment analyser un conflit où l’appartenance religieuse est mobilisée ?', 'mcq', '["En démêlant les enjeux de terre, de pouvoir et de mémoire derrière le marqueur religieux","En le lisant comme purement religieux","En ignorant la dimension religieuse","En le rapportant à un seul acteur"]'::jsonb, 0, 'Lire un conflit comme purement religieux est presque toujours une erreur d’analyse.', 7),
    ('27344d5a-d7d3-514a-a504-e2b8bd22f4e8'::uuid, 'f5bd5eac-8bf8-53d1-be4b-84ba3f9e0b55'::uuid, 'Quel texte international garantit la liberté de pensée, de conscience et de religion en Europe ?', 'mcq', '["L’article 9 de la Convention européenne des droits de l’homme","L’article 11 de la Déclaration de 1789","La loi de 1905","Le traité de Lisbonne"]'::jsonb, 0, 'L’article 18 de la Déclaration universelle de 1948 le fait au niveau mondial.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('hggsp');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('hggsp')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 275 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 275 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
